import{_ as e,o as a,c as r,a2 as s}from"./chunks/framework.hwbV7reR.js";const u=JSON.parse('{"title":"Диагностика и метрики","description":"","frontmatter":{},"headers":[],"relativePath":"observability.md","filePath":"observability.md","lastUpdated":1791695486000}'),d={name:"observability.md"};function i(o,t,n,p,l,h){return a(),r("div",null,[...t[0]||(t[0]=[s(`<h1 id="диагностика-и-метрики" tabindex="-1">Диагностика и метрики <a class="header-anchor" href="#диагностика-и-метрики" aria-label="Permalink to &quot;Диагностика и метрики&quot;">​</a></h1><p>Диагностика включается при стандартном запуске через bootstrap: JSON-события пишутся в stderr и попадают в journald, метрики доступны через служебный HTTP API. Внешний Prometheus или Grafana не требуются для работы VPN. Их установка и панели визуализации не входят в этот этап.</p><h2 id="корреляция-запросов" tabindex="-1">Корреляция запросов <a class="header-anchor" href="#корреляция-запросов" aria-label="Permalink to &quot;Корреляция запросов&quot;">​</a></h2><p>Каждый входящий HTTP-запрос получает новый <code>X-Request-ID</code> (32 шестнадцатеричных символа), включая ошибки авторизации и валидации. Переданный вызывающей стороной идентификатор не принимается: в нём могут оказаться секреты или чужая корреляция. Backend может сохранить возвращённый заголовок рядом со своим идентификатором. Тело ответа и коды ошибок v1/v2 сохраняют прежний контракт.</p><p>Тот же идентификатор передаётся агентам в X-Request-ID. Для операции также передаётся X-Operation-Ref. Старый агент может игнорировать эти заголовки; чтение и сохранение корреляции на стороне самого агента потребует отдельной реализации. Контекст переносится в потоки параллельной проверки узлов и не смешивается между запросами.</p><p>Повтор запроса получает новый request_id. <code>operation_ref</code> позволяет связать попытки одной операции: для переключения он вычисляется из connection_id и сохранённого operation_id. Фоновое продолжение сохраняет эту ссылку. Она предназначена только для диагностики и не заменяет ключ идемпотентности или авторизацию.</p><p><code>operation_ref</code> и <code>node_ref</code> — первые 24 hex-символа SHA-256 от строк с 8-байтовыми префиксами длины; функция <code>application.telemetry.reference</code> задаёт точный формат. Для node_ref используется node_id. Это псевдонимы, а не гарантия анонимности: известный идентификатор можно сопоставить с его хешем. Они не являются метками метрик.</p><h2 id="события" tabindex="-1">События <a class="header-anchor" href="#события" aria-label="Permalink to &quot;События&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">journalctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vpn-orchestrator.service</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vpn-orchestrator-recovery.service</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vpn-orchestrator-leases.service</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --since</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;1 hour ago&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cat</span></span></code></pre></div><p>Завершение этапа записывается как JSON с фиксированными полями: timestamp, event, stage, action, reason, duration_ms, request_id и, если применимо, operation_ref, node_ref, http_status. Временные интервалы измеряются монотонными часами.</p><p>Этапы включают HTTP-запрос, создание, выбор/проверку узла, запрос агента, получение параметров, экспорт, переключение, recovery, фоновую сверку и heartbeat. У запросов агента action различает health, list, create, connection и мутации. Вложенные этапы пересекаются: складывать их длительности или считать их количество числом пользователей нельзя. Событие завершения появляется после возврата или ошибки; отдельных событий начала и длительных распределённых traces пока нет.</p><table tabindex="0"><thead><tr><th>reason</th><th>Интерпретация</th></tr></thead><tbody><tr><td>ok</td><td>Этот этап завершился без ошибки; не подтверждает интернет у пользователя</td></tr><tr><td>deadline</td><td>Исчерпан общий бюджет прикладной операции</td></tr><tr><td>saturated</td><td>Переполнена локальная очередь или истекло ожидание допуска</td></tr><tr><td>timeout</td><td>HTTP-клиент достиг своего таймаута</td></tr><tr><td>tls</td><td>В цепочке транспортной ошибки обнаружена SSL-ошибка</td></tr><tr><td>network</td><td>Другая транспортная ошибка; не доказательство блокировки</td></tr><tr><td>upstream_status</td><td>Агент вернул неуспешный HTTP-статус</td></tr><tr><td>invalid_response</td><td>Не удалось декодировать/проверить ответ или нарушен лимит/требование no-store</td></tr><tr><td>identity_mismatch</td><td>Ответ не соответствует ожидаемому узлу/назначению</td></tr><tr><td>waiting</td><td>Незавершённая операция, блокировка или ожидание lease</td></tr><tr><td>unavailable / rejected</td><td>Сервисная ошибка доступности или отклонённая операция</td></tr><tr><td>unauthorized / validation</td><td>Отказ авторизации или проверка входных данных HTTP</td></tr><tr><td>internal_error / cancelled</td><td>Неожиданный сбой или отмена операции</td></tr></tbody></table><p>Если библиотека не сохраняет исходную SSL-ошибку, TLS-сбой может попасть в network. Произвольный текст исключений не анализируется и не записывается. Внешний статус node_unavailable остаётся прежним; подробная категория доступна в диагностике.</p><p>В событиях нет URL, query string, IP-адресов, имён устройств, входных/выходных тел, токенов и VPN-документов. Ошибка при записи события не отменяет VPN-операцию. Логи синхронные: медленный stderr может добавить задержку, поэтому состояние системного журнала также требует контроля. Retention задаётся оператором в journald; дополнительно bootstrap сохраняет безопасные события в ограниченный EventTail для <a href="./panel.html">панели</a>: два файла по 256 КиБ, до 100 последних событий в ответе. Межпроцессная блокировка не ожидается: при конкуренции или ошибке событие может пропасть. Это диагностическая выборка, не надёжный аудит. Запись на медленный диск может добавить задержку; ошибки записи не отменяют операцию.</p><h2 id="метрики" tabindex="-1">Метрики <a class="header-anchor" href="#метрики" aria-label="Permalink to &quot;Метрики&quot;">​</a></h2><p><code>GET /internal/v1/metrics</code> использует существующий backend Bearer-токен и no-store. Сервис по умолчанию слушает loopback. Не публикуйте endpoint через открытый reverse proxy; токен даёт полномочия backend, а не только чтение метрик. Отдельная панель имеет только API обзора; она не открывает этот endpoint метрик своим ключом. Не размещайте токен в командной строке, истории shell или открытом конфиге сборщика.</p><p>Используется стандартный prometheus-client. Собственная registry не включает сторонние/default process collectors. Метки stage, action и reason ограничены перечислениями; идентификаторов, произвольных путей и пользовательских значений нет.</p><table tabindex="0"><thead><tr><th>Метрика</th><th>Назначение</th></tr></thead><tbody><tr><td>orchestrator_operations_total</td><td>Количество завершённых этапов по stage/action/reason</td></tr><tr><td>orchestrator_operation_duration_seconds</td><td>Гистограмма длительности по stage/action</td></tr><tr><td kind="create">orchestrator_pending_operations</td><td>Назначения без подтверждённого remote_id</td></tr><tr><td kind="switch">orchestrator_pending_operations</td><td>Незавершённые переключения</td></tr><tr><td>orchestrator_oldest_pending_seconds</td><td>Возраст самого старого незавершённого переключения</td></tr><tr><td>orchestrator_journal_snapshot_success</td><td>Успешность последнего чтения локального журнала</td></tr></tbody></table><p>Просмотр метрик не обращается к VPN-агентам. Очередь читается из SQLite в режиме read-only без резервирования записи, с коротким ожиданием блокировки. Если БД недоступна, snapshot_success равен 0, прежние значения очереди могут быть устаревшими. Пустая очередь не означает, что у всех пользователей исправно работает VPN.</p><p>Счётчики и гистограммы относятся к текущему процессу API и сбрасываются при его перезапуске. Короткоживущие workers пишут события в journald; их счётчики не суммируются в API-процессе. Состояние очереди читается из общего постоянного журнала. Экземпляры API имеют отдельные registry: при нескольких процессах их нужно собирать раздельно. Этот выпуск не добавляет multiprocess Prometheus storage.</p><p>Пример p95 времени выбора узла при наличии Prometheus:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>histogram_quantile(0.95,</span></span>
<span class="line"><span>  sum by (le) (rate(orchestrator_operation_duration_seconds_bucket{stage=&quot;select_node&quot;,action=&quot;none&quot;}[5m]))</span></span>
<span class="line"><span>)</span></span></code></pre></div><p>Для расследования задержки найдите HTTP-событие по request_id, затем этапы выбора узла, обращения к агенту и получения конфигурации. Для повторяющегося переключения сопоставьте operation_ref в API и worker-журнале. Проверяйте конкретную причину: сбой управляющего API не подтверждает сбой пользовательского туннеля.</p><p>Этап <code>agent_queue</code> измеряет ожидание допуска к общему и узловому лимиту. <a href="./runtime-limits.html">Границы нагрузки и сроков</a> применяются независимо от сбора метрик.</p>`,24)])])}const _=e(d,[["render",i]]);export{u as __pageData,_ as default};
